from pathlib import Path
import json,re
sources=json.loads(Path('content/tongbian-chinese/sources.json').read_text());books={b['id']:b for b in sources['books']};groups={}
def add(book,title,author,dynasty,lines,word,meaning,mw,idea,iw):
 lines=['鹅，鹅，鹅，','曲项向天歌。','白毛浮绿水，','红掌拨清波。'] if title=='咏鹅' else re.findall(r'[^，。！？]+[，。！？]',lines);assert len(lines)==4,(title,lines)
 ps=Path('/tmp/learn-chinese/'+book+'.txt').read_text().split('\f');needle=re.sub('[^\u4e00-\u9fff]','',lines[0]);pg=next((i+1 for i,t in enumerate(ps) if i>=5 and needle in ''.join(re.findall('[\u4e00-\u9fff]',t))),None);assert pg,(book,title)
 b=books[book];unit=next(u['number'] for u in reversed(b['units']) if u['startPdfPage']<=pg)
 authors=[a for a in ['李白','杜甫','白居易','王维','苏轼','陆游'] if a!=author][:3]
 p=dict(title=title,author=author,dynasty=dynasty,unit=unit,page=pg-5,lines=lines,otherAuthors=authors,nextWrong=[lines[2].rstrip('，。'),lines[3].rstrip('，。'),'千山鸟飞绝'],word=word,meaning=meaning,meaningWrong=mw.split('/'),meaningExplanation=f'在《{title}》中，“{word}”指{meaning}。',idea=idea,ideaWrong=iw.split('/'),ideaExplanation=f'结合诗句可知：{idea}。')
 assert len(p['meaningWrong'])==3 and len(p['ideaWrong'])==3
 groups.setdefault(book,[]).append(p)
add('g1a','咏鹅','骆宾王','唐','鹅，鹅，鹅，曲项向天歌。白毛浮绿水，红掌拨清波。','曲项','弯着脖子','折断翅膀/张开脚掌/躲进树林','诗中描写了鹅的外形和动作','诗中主要写下雪/鹅的羽毛被写成黑色/鹅正在爬高山')
add('g1a','悯农（其二）','李绅','唐','锄禾日当午，汗滴禾下土。谁知盘中餐，粒粒皆辛苦。','皆','都','很少/已经/有时','粮食来之不易，应当珍惜','粮食完全不需要劳动/农民只在夜里劳动/每粒粮食都会自己飞来')
