add('g2b','咏柳','贺知章','唐','碧玉妆成一树高，万条垂下绿丝绦。不知细叶谁裁出，二月春风似剪刀。','丝绦','丝编的带子','石头砌的墙/木制的船桨/金属的钟','诗人把春风比作剪刀，赞美春天的柳树','诗人说柳叶真由工匠用铁剪刀剪成/诗中描写雪山/柳条被比成金色麦粒')
add('g3a','山行','杜牧','唐','远上寒山石径斜，白云生处有人家。停车坐爱枫林晚，霜叶红于二月花。','坐','因为','坐下休息/座位/坐船','诗人喜爱深秋枫林的美丽景色','诗人厌恶枫叶的颜色/诗中描写夏天海滨/诗人是因为车坏了才停车')
add('g3a','望洞庭','刘禹锡','唐','湖光秋月两相和，潭面无风镜未磨。遥望洞庭山水翠，白银盘里一青螺。','两相和','湖光与月色互相协调','两个人在争吵/两座山移动/两条船碰撞','诗人把洞庭湖比作银盘，把湖中山比作青螺','湖水真的变成了金属/诗中主要写喧闹的市场/青螺是作者正在吃的午餐')
add('g3b','绝句','杜甫','唐','迟日江山丽，春风花草香。泥融飞燕子，沙暖睡鸳鸯。','迟日','春天的白天','迟到的一天/下雨的夜晚/秋天的黄昏','诗句描绘了明丽和谐的春日景色','燕子都已冻住/鸳鸯正在高空飞翔/全诗写的是冬夜风雪')
add('g3b','九月九日忆山东兄弟','王维','唐','独在异乡为异客，每逢佳节倍思亲。遥知兄弟登高处，遍插茱萸少一人。','异乡','他乡，家乡以外的地方','家中庭院/熟悉的卧室/亲人的姓名','诗人在重阳佳节思念远方的亲人','诗人认为亲情毫不重要/兄弟正在庆祝元宵/诗人就在兄弟身边一起登高')
add('g4a','题西林壁','苏轼','宋','横看成岭侧成峰，远近高低各不同。不识庐山真面目，只缘身在此山中。','缘','因为','边缘/缘分结束/石头的颜色','观察角度不同，所见景象可能不同','从任何角度看山都完全一样/只看局部就一定能认识全部/诗中只在介绍船只')
add('g4a','雪梅','卢钺','宋','梅雪争春未肯降，骚人阁笔费评章。梅须逊雪三分白，雪却输梅一段香。','逊','不及，比不上','走得更快/完全消失/互相交换','梅与雪各有长处，不宜只凭一方面评判','梅花在白和香两方面都胜过雪/雪有梅花那样的香气/诗人只赞美夏天的荷花')
add('g4b','四时田园杂兴（其二十五）','范成大','宋','梅子金黄杏子肥，麦花雪白菜花稀。日长篱落无人过，惟有蜻蜓蛱蝶飞。','篱落','篱笆','楼上的窗户/河底的沙石/远处的大海','诗中展现初夏田园景物与宁静气氛','诗中描写隆冬冰雪/篱笆旁挤满过路人/诗中没有昆虫出现')
add('g4b','墨梅','王冕','元','我家洗砚池头树，朵朵花开淡墨痕。不要人夸好颜色，只留清气满乾坤。','乾坤','天地','一个人的姓名/厨房用具/一条小溪','诗人借梅花表达不求虚名、保持高洁的志向','诗人只想得到别人夸颜色/梅花被写成追逐名利的人/清气专指烟囱的黑烟')
add('g5a','示儿','陆游','宋','死去元知万事空，但悲不见九州同。王师北定中原日，家祭无忘告乃翁。','乃翁','你们的父亲','你们的邻居/遥远的商人/陌生的儿童','诗人临终仍牵挂国家统一','诗人只惦记家中摆设/诗人认为国家统一毫无意义/诗人让孩子忘掉所有往事')
add('g5a','枫桥夜泊','张继','唐','月落乌啼霜满天，江枫渔火对愁眠。姑苏城外寒山寺，夜半钟声到客船。','夜泊','夜里停船靠岸','夜间奔跑/白天登山/清晨耕田','夜景和钟声衬托了旅人的愁绪','诗人正在描写欢快的赛场/钟声来自正午课堂/客船停在沙漠里')
add('g5b','稚子弄冰','杨万里','宋','稚子金盆脱晓冰，彩丝穿取当银钲。敲成玉磬穿林响，忽作玻璃碎地声。','稚子','年幼的孩子','高大的树木/成年军人/遥远的山峰','孩子玩冰的细节表现了童年的乐趣','诗中说冰永远不会碎/孩子在夏天采摘棉花/全诗只写老人独自捕鱼')
add('g5b','从军行','王昌龄','唐','青海长云暗雪山，孤城遥望玉门关。黄沙百战穿金甲，不破楼兰终不还。','穿','磨破','穿上新衣/从洞里走过/把东西串起来','诗句表现了将士守边报国、战斗到底的决心','将士在战争前已经放弃/诗人只写宫廷歌舞/金甲永远不会磨损')
add('g6a','宿建德江','孟浩然','唐','移舟泊烟渚，日暮客愁新。野旷天低树，江清月近人。','日暮','傍晚','清晨/正午/明年','诗中写羁旅愁思，也写江清月近的夜景','诗人正午在市场买菜/诗中没有江水/全诗表达对战争的欢呼')
add('g6a','书湖阴先生壁','王安石','宋','茅檐长扫净无苔，花木成畦手自栽。一水护田将绿绕，两山排闼送青来。','排闼','推开门','修理屋顶/清洗砚台/闭眼睡觉','后两句赋予山水人的动作，表现环境清幽','山水真的长出了人的手脚/诗中院子到处垃圾无人清扫/诗人只描写荒凉沙漠')
add('g6b','马诗','李贺','唐','大漠沙如雪，燕山月似钩。何当金络脑，快走踏清秋。','何当','什么时候才能','从来没有/一定已经/为何停止','诗人借马表达渴望施展才华、建功立业的愿望','诗人只说明马的饲料价格/诗人希望永远不得施展才能/诗中描写盛夏莲花')
add('g6b','泊船瓜洲','王安石','宋','京口瓜洲一水间，钟山只隔数重山。春风又绿江南岸，明月何时照我还。','还','返回','另外/仍旧/归还借来的物品','春景中流露出诗人希望回到家乡的心情','诗人完全不想返回/诗中描写的是冰封冬夜/诗人只在赞美边塞战争')
